<template><section class="max-w-2xl"><div class="flex justify-between mb-6"><h2 class="text-2xl font-bold">Chi tiết tài khoản</h2><router-link class="text-primary" :to="{name:'admin-account-edit',params:{id:route.params.id}}">Chỉnh sửa</router-link></div><p v-if="error" class="text-error">{{ error }}</p><p v-else-if="!account" class="text-gray-400">Đang tải…</p><div v-else class="grid grid-cols-1 sm:grid-cols-2 gap-4"><div v-for="(value,key) in account" :key="key" class="rounded bg-white/5 p-4"><p class="text-gray-400 text-sm">{{ key }}</p><p>{{ value }}</p></div></div><div v-if="account" class="mt-6"><button class="px-4 py-2 rounded bg-error text-white" @click="toggle">{{ account.status === 'ACTIVE' ? 'Khóa tài khoản' : 'Mở khóa tài khoản' }}</button><p v-if="message" class="mt-3 text-primary">{{ message }}</p></div></section></template>
<script setup>
import { onMounted, ref } from 'vue'; import { useRoute } from 'vue-router'; import { adminApi } from '../../api/adminService'; const route=useRoute(); const account=ref(null); const error=ref(''); const message=ref(''); onMounted(async()=>{try{account.value=(await adminApi.account(route.params.id)).data}catch(e){error.value='Không thể tải tài khoản.'}}); const toggle=async()=>{const target=account.value.status==='ACTIVE'?'INACTIVE':'ACTIVE'; if(!window.confirm(`Xác nhận chuyển trạng thái thành ${target}?`))return; try{account.value=(await adminApi.setAccountStatus(route.params.id,target)).data;message.value='Đã cập nhật trạng thái.'}catch(e){error.value=e.response?.data?.message||'Không thể cập nhật trạng thái.'}}</script>
